CREATE OR REPLACE FUNCTION public.set_purchase_orders_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_field_cycle_v1(p_cycle_id uuid, p_close_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_cycle_id is null then
    raise exception 'p_cycle_id is required';
  end if;

  select c.organization_id
    into v_org_id
  from public.field_cycles c
  where c.id = p_cycle_id
  limit 1;

  if v_org_id is null then
    raise exception 'Field cycle not found';
  end if;

  if not exists (
    select 1
    from public.org_memberships m
    where m.organization_id = v_org_id
      and m.user_id = auth.uid()
      and coalesce(m.is_active, true) = true
      and m.role in ('owner', 'admin')
  ) then
    raise exception 'No access: owner/admin only';
  end if;

  update public.field_cycles
  set
    status = 'CLOSED',
    closed_by = auth.uid(),
    closed_at = now(),
    close_note = nullif(trim(coalesce(p_close_note, '')), ''),
    updated_at = now()
  where id = p_cycle_id
    and status = 'OPEN';

  if not found then
    raise exception 'Field cycle is already closed or not found';
  end if;

  return p_cycle_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_my_commission_received_v1(p_payout_id uuid, p_note text DEFAULT NULL::text)
 RETURNS TABLE(payout_id uuid, status text, received_at timestamp with time zone, received_note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_membership_id uuid;
  v_my_membership_id uuid;
  v_role text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_payout_id is null then
    raise exception 'p_payout_id is required';
  end if;

  select sp.organization_id, sp.membership_id
    into v_org_id, v_membership_id
  from public.staff_commission_payouts sp
  where sp.id = p_payout_id
  limit 1;

  if v_org_id is null then
    raise exception 'Payout not found';
  end if;

  select om.id, lower(coalesce(om.role, ''))
    into v_my_membership_id, v_role
  from public.org_memberships om
  where om.user_id = auth.uid()
    and om.organization_id = v_org_id
    and coalesce(om.is_active, true) = true
  limit 1;

  if v_my_membership_id is null then
    raise exception 'No org membership';
  end if;

  if v_role <> 'staff' then
    raise exception 'This action is for STAFF only';
  end if;

  if v_my_membership_id <> v_membership_id then
    raise exception 'You can only confirm your own payout';
  end if;

  update public.staff_commission_payouts sp
     set status = 'RECEIVED',
         received_at = now(),
         received_note = nullif(trim(coalesce(p_note, '')), ''),
         updated_at = now(),
         updated_by = auth.uid()
   where sp.id = p_payout_id;

  return query
  select
    sp.id as payout_id,
    sp.status,
    sp.received_at,
    sp.received_note
  from public.staff_commission_payouts sp
  where sp.id = p_payout_id
  limit 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_expense(p_store_id uuid, p_amount numeric, p_category_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_expense_date date DEFAULT CURRENT_DATE)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_org_id uuid;
  v_role text;
  v_cat_id uuid;
  v_cat_name text;
  v_expense_id uuid;
begin
  if p_store_id is null then
    raise exception 'Missing store';
  end if;

  select s.organization_id into v_org_id
  from public.stores s
  where s.id = p_store_id;

  if v_org_id is null then
    raise exception 'Store not found';
  end if;

  -- Get caller role in this org
  select m.role into v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_org_id
  limit 1;

  if v_role is null then
    raise exception 'No membership in this organization';
  end if;

  -- Staff must be assigned to the store
  if v_role = 'staff' then
    if not exists (
      select 1
      from public.org_memberships m
      join public.org_membership_stores ms on ms.membership_id = m.id
      where m.user_id = auth.uid()
        and m.organization_id = v_org_id
        and m.role = 'staff'
        and ms.store_id = p_store_id
    ) then
      raise exception 'No access to this store';
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  -- Category handling:
  -- - Owner/Admin can create category if missing
  -- - Staff can ONLY use existing category (no auto-create)
  if p_category_name is not null and length(trim(p_category_name)) > 0 then
    v_cat_name := trim(p_category_name);

    select ec.id into v_cat_id
    from public.expense_categories ec
    where ec.organization_id = v_org_id
      and upper(ec.name) = upper(v_cat_name)
    limit 1;

    if v_cat_id is null then
      if v_role in ('owner','admin') then
        insert into public.expense_categories (organization_id, name)
        values (v_org_id, v_cat_name)
        returning id into v_cat_id;
      else
        raise exception 'Category not found (staff cannot create categories)';
      end if;
    end if;
  end if;

  insert into public.expenses (
    organization_id,
    store_id,
    category_id,
    category_name,
    amount,
    note,
    expense_date,
    created_by
  )
  values (
    v_org_id,
    p_store_id,
    v_cat_id,
    v_cat_name,
    p_amount,
    p_note,
    coalesce(p_expense_date, current_date),
    auth.uid()
  )
  returning id into v_expense_id;

  return v_expense_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_expense(p_store_id uuid, p_amount numeric, p_category_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_expense_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_org_id uuid;
  v_role text;
  v_membership_id uuid;
  v_cat_id uuid;
  v_cat_name text;
  v_expense_id uuid;
  v_payment_method text;
begin
  if p_store_id is null then
    raise exception 'Missing store';
  end if;

  select s.organization_id into v_org_id
  from public.stores s
  where s.id = p_store_id;

  if v_org_id is null then
    raise exception 'Store not found';
  end if;

  -- 🔥 Get membership record
  select m.id, m.role
  into v_membership_id, v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_org_id
  limit 1;

  if v_membership_id is null then
    raise exception 'No membership in this organization';
  end if;

  -- Staff must be assigned to the store
  if v_role = 'staff' then
    if not exists (
      select 1
      from public.org_membership_stores ms
      where ms.membership_id = v_membership_id
        and ms.store_id = p_store_id
    ) then
      raise exception 'No access to this store';
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  -- Accept both p_category_name and p_category
  if coalesce(p_category_name, p_category) is not null
     and length(trim(coalesce(p_category_name, p_category))) > 0 then

    v_cat_name := trim(coalesce(p_category_name, p_category));

    select ec.id into v_cat_id
    from public.expense_categories ec
    where ec.organization_id = v_org_id
      and upper(ec.name) = upper(v_cat_name)
    limit 1;

    if v_cat_id is null then
      if v_role in ('owner','admin') then
        insert into public.expense_categories (organization_id, name)
        values (v_org_id, v_cat_name)
        returning id into v_cat_id;
      else
        raise exception 'Category not found (staff cannot create categories)';
      end if;
    end if;
  end if;

  v_payment_method := nullif(trim(coalesce(p_payment_method, '')), '');
  if v_payment_method is not null then
    v_payment_method := upper(v_payment_method);
  end if;

  insert into public.expenses (
    organization_id,
    store_id,
    category_id,
    category_name,
    amount,
    note,
    payment_method,
    expense_date,
    created_by_membership_id
  )
  values (
    v_org_id,
    p_store_id,
    v_cat_id,
    v_cat_name,
    p_amount,
    p_note,
    v_payment_method,
    coalesce(p_expense_date, current_date),
    v_membership_id
  )
  returning id into v_expense_id;

  return v_expense_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_expense_v2(p_store_id uuid, p_amount numeric, p_category text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_expense_date date DEFAULT NULL::date, p_category_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_role text;
  v_membership_id uuid;
  v_cat_id uuid;
  v_cat_name text;
  v_expense_id uuid;
  v_payment_method text;
  v_store_expense_allowed boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_store_id is null then
    raise exception 'Missing store';
  end if;

  select
    s.organization_id,
    coalesce(s.staff_can_manage_expense, false)
  into
    v_org_id,
    v_store_expense_allowed
  from public.stores s
  where s.id = p_store_id;

  if v_org_id is null then
    raise exception 'Store not found';
  end if;

  select
    m.id,
    lower(coalesce(m.role, ''))
  into
    v_membership_id,
    v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_org_id
    and coalesce(m.is_active, true) = true
  limit 1;

  if v_membership_id is null then
    raise exception 'No membership in this organization';
  end if;

  if v_role = 'staff' then
    if not exists (
      select 1
      from public.org_membership_stores ms
      where ms.membership_id = v_membership_id
        and ms.store_id = p_store_id
    ) then
      raise exception 'No access to this store';
    end if;

    if not v_store_expense_allowed then
      raise exception 'Expense permission disabled for staff in this store';
    end if;
  elsif v_role not in ('owner', 'admin') then
    raise exception 'No access';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  if coalesce(p_category_name, p_category) is not null
     and length(trim(coalesce(p_category_name, p_category))) > 0 then
    v_cat_name := trim(coalesce(p_category_name, p_category));

    select ec.id
    into v_cat_id
    from public.expense_categories ec
    where ec.organization_id = v_org_id
      and upper(ec.name) = upper(v_cat_name)
    limit 1;

    if v_cat_id is null then
      insert into public.expense_categories (organization_id, name)
      values (v_org_id, v_cat_name)
      returning id into v_cat_id;
    end if;
  end if;

  v_payment_method := nullif(trim(coalesce(p_payment_method, '')), '');

  if v_payment_method is not null then
    v_payment_method := upper(v_payment_method);
  end if;

  insert into public.expenses (
    organization_id,
    store_id,
    category_id,
    category_name,
    amount,
    note,
    payment_method,
    expense_date,
    created_by,
    created_by_membership_id
  )
  values (
    v_org_id,
    p_store_id,
    v_cat_id,
    v_cat_name,
    p_amount,
    p_note,
    v_payment_method,
    coalesce(p_expense_date, current_date),
    auth.uid(),
    v_membership_id
  )
  returning id into v_expense_id;

  return v_expense_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_purchase_order_from_restock_v1(p_org_id uuid, p_store_id uuid, p_items jsonb, p_supplier_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_membership_id uuid;
  v_role text;
  v_has_access boolean := false;
  v_order_id uuid;
  v_order_no text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Order items are required';
  end if;

  select m.id, lower(coalesce(m.role, ''))
  into v_membership_id, v_role
  from public.org_memberships m
  where m.organization_id = p_org_id
    and m.user_id = auth.uid()
    and coalesce(m.is_active, true) = true
  limit 1;

  if v_membership_id is null then
    raise exception 'Access denied';
  end if;

  if v_role in ('owner', 'admin') then
    v_has_access := true;
  else
    select exists (
      select 1
      from public.org_membership_stores ms
      where ms.membership_id = v_membership_id
        and ms.store_id = p_store_id
    ) into v_has_access;
  end if;

  if not v_has_access then
    raise exception 'Store access denied';
  end if;

  v_order_no := 'PO-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.purchase_orders (
    organization_id,
    store_id,
    order_no,
    status,
    supplier_name,
    notes,
    created_by
  )
  values (
    p_org_id,
    p_store_id,
    v_order_no,
    'PENDING',
    nullif(trim(coalesce(p_supplier_name, '')), ''),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  )
  returning id into v_order_id;

  insert into public.purchase_order_items (
    purchase_order_id,
    organization_id,
    store_id,
    product_id,
    product_name,
    sku,
    current_qty,
    alert_level,
    order_qty
  )
  select
    v_order_id,
    p_org_id,
    p_store_id,
    p.id,
    coalesce(nullif(p.name, ''), nullif(trim(x.item->>'product_name'), ''), 'Custom Item')::text,
    coalesce(p.sku, nullif(trim(x.item->>'sku'), ''))::text,
    coalesce(p.qty_on_hand, 0)::numeric,
    coalesce(public.get_inventory_threshold(p_store_id, p.id), 0)::numeric,
    greatest(coalesce((x.item->>'order_qty')::numeric, 0), 0)::numeric
  from jsonb_array_elements(p_items) as x(item)
  left join public.products p
    on nullif(x.item->>'product_id', '') is not null
   and p.id = (x.item->>'product_id')::uuid
   and p.organization_id = p_org_id
   and p.store_id = p_store_id
  where greatest(coalesce((x.item->>'order_qty')::numeric, 0), 0) > 0
    and coalesce(nullif(p.name, ''), nullif(trim(x.item->>'product_name'), '')) is not null;

  if not exists (
    select 1 from public.purchase_order_items i
    where i.purchase_order_id = v_order_id
  ) then
    delete from public.purchase_orders where id = v_order_id;
    raise exception 'At least one valid item is required';
  end if;

  return v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_expense_v2(p_expense_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exp record;
  v_role text;
  v_membership_id uuid;
  v_staff_allowed boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select e.*, s.staff_can_manage_expense
  into v_exp
  from public.expenses e
  join public.stores s on s.id = e.store_id
  where e.id = p_expense_id;

  if v_exp.id is null then
    raise exception 'Expense not found';
  end if;

  select m.id, lower(coalesce(m.role, ''))
  into v_membership_id, v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_exp.organization_id
    and coalesce(m.is_active, true) = true
  limit 1;

  if v_membership_id is null then
    raise exception 'No access';
  end if;

  if v_role = 'staff' then
    v_staff_allowed := coalesce(v_exp.staff_can_manage_expense, false);

    if not v_staff_allowed then
      raise exception 'Expense permission disabled for staff in this store';
    end if;

    if v_exp.created_by_membership_id <> v_membership_id
       and v_exp.created_by <> auth.uid() then
      raise exception 'Staff can delete own expense only';
    end if;

  elsif v_role = 'admin' then
    if exists (
      select 1
      from public.org_memberships om_owner
      where om_owner.organization_id = v_exp.organization_id
        and lower(coalesce(om_owner.role, '')) = 'owner'
        and (
          om_owner.id = v_exp.created_by_membership_id
          or om_owner.user_id = v_exp.created_by
        )
    ) then
      raise exception 'Admin cannot delete owner expense';
    end if;

  elsif v_role <> 'owner' then
    raise exception 'No access';
  end if;

  delete from public.expenses
  where id = p_expense_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_expense_summary(p_store_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(total numeric, count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_from date;
  v_to date;
begin
  select s.organization_id
  into v_org_id
  from public.stores s
  where s.id = p_store_id;

  if v_org_id is null then
    raise exception 'Store not found';
  end if;

  if not exists (
    select 1
    from public.org_memberships m
    where m.user_id = auth.uid()
      and m.organization_id = v_org_id
      and m.role in ('owner','admin')
  ) then
    raise exception 'No access (owner/admin only)';
  end if;

  v_from := coalesce(p_from, current_date);
  v_to := coalesce(p_to, current_date) + 1;

  return query
  select
    coalesce(sum(e.amount), 0) as total,
    count(*)::int as count
  from public.expenses e
  where e.store_id = p_store_id
    and e.expense_date >= v_from
    and e.expense_date < v_to;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_expense_summary_v2(p_store_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(total numeric, count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_role text;
  v_membership_id uuid;
  v_from date;
  v_to_exclusive date;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select s.organization_id into v_org_id
  from public.stores s
  where s.id = p_store_id;

  if v_org_id is null then
    raise exception 'Store not found';
  end if;

  select m.id, lower(coalesce(m.role, ''))
  into v_membership_id, v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_org_id
    and coalesce(m.is_active, true) = true
  limit 1;

  if v_membership_id is null then
    raise exception 'No access';
  end if;

  if v_role = 'staff' then
    if not exists (
      select 1
      from public.org_membership_stores ms
      where ms.membership_id = v_membership_id
        and ms.store_id = p_store_id
    ) then
      raise exception 'No access to this store';
    end if;
  elsif v_role not in ('owner', 'admin') then
    raise exception 'No access';
  end if;

  v_from := coalesce(p_from, current_date);
  v_to_exclusive := coalesce(p_to, current_date) + 1;

  return query
  select
    coalesce(sum(e.amount), 0)::numeric as total,
    count(*)::int as count
  from public.expenses e
  where e.store_id = p_store_id
    and e.expense_date >= v_from
    and e.expense_date < v_to_exclusive
    and (
      v_role = 'owner'
      or (
        v_role = 'staff'
        and (
          e.created_by_membership_id = v_membership_id
          or e.created_by = auth.uid()
        )
      )
      or (
        v_role = 'admin'
        and not exists (
          select 1
          from public.org_memberships om_owner
          where om_owner.organization_id = v_org_id
            and lower(coalesce(om_owner.role, '')) = 'owner'
            and (
              om_owner.id = e.created_by_membership_id
              or om_owner.user_id = e.created_by
            )
        )
      )
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_stock_in_value_v2(p_org_id uuid, p_store_id uuid, p_date_from date, p_date_to date)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_membership_id uuid;
  v_role text;
  v_value numeric;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select membership_id, role
    into v_membership_id, v_role
  from public._resolve_my_membership_in_org(p_org_id);

  if v_membership_id is null then
    raise exception 'Not a member of this organization';
  end if;

  if v_role = 'staff' and p_store_id is null then
    raise exception 'Staff must query by store';
  end if;

  if p_store_id is not null then
    perform public._require_store_access_in_org(p_org_id, p_store_id);
  end if;

  if p_date_from is null or p_date_to is null then
    raise exception 'date_from and date_to are required';
  end if;

  if p_date_from > p_date_to then
    raise exception 'date_from cannot be after date_to';
  end if;

  select coalesce(
    sum(
      coalesce(sm.amount, 0)::numeric
      * coalesce(nullif(p.cost, 0), p.cost_price, 0)::numeric
    ),
    0
  )::numeric
  into v_value
  from public.stock_movements sm
  join public.products p on p.id = sm.product_id
  where sm.organization_id = p_org_id
    and p.organization_id = p_org_id
    and (p_store_id is null or sm.store_id = p_store_id)
    and sm.created_at::date between p_date_from and p_date_to
    and coalesce(sm.amount, 0) > 0
    and upper(coalesce(sm.mode, '')) in (
      'ADD',
      'IN',
      'STOCK_IN',
      'RECEIVE',
      'RECEIVED',
      'PURCHASE',
      'INBOUND'
    );

  return coalesce(v_value, 0)::numeric;
end;
$function$

CREATE OR REPLACE FUNCTION public.gp_confirm_my_payout_received_v1(p_payout_id uuid, p_confirmation_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_partner_id uuid;
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if p_payout_id is null then
    raise exception 'Payout id is required';
  end if;

  select gp.id
    into v_partner_id
  from public.growth_partner_profiles gp
  where gp.user_id = auth.uid()
  limit 1;

  if v_partner_id is null then
    raise exception 'Partner profile not found';
  end if;

  select upper(coalesce(p.payout_status, ''))
    into v_status
  from public.growth_partner_payouts p
  where p.id = p_payout_id
    and p.partner_id = v_partner_id
  limit 1;

  if v_status is null then
    raise exception 'Payout not found for this partner';
  end if;

  if v_status = 'CONFIRMED' then
    return p_payout_id;
  end if;

  if v_status <> 'PAID' then
    raise exception 'Only PAID payout can be confirmed';
  end if;

  update public.growth_partner_payouts p
     set payout_status = 'CONFIRMED',
         receiver_confirmed_at = now(),
         receiver_confirmed_by = auth.uid(),
         receiver_confirmation_note = nullif(trim(coalesce(p_confirmation_note, '')), ''),
         updated_at = now()
   where p.id = p_payout_id
     and p.partner_id = v_partner_id;

  return p_payout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.open_field_cycle_v1(p_store_id uuid, p_title text, p_target_amount numeric DEFAULT 0, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_cycle_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select s.organization_id
  into v_org_id
  from public.stores s
  where s.id = p_store_id
    and s.store_type = 'FIELD_PROCUREMENT'
    and coalesce(s.is_active, true) = true;

  if v_org_id is null then
    raise exception 'Invalid Field Procurement store';
  end if;

  if not exists (
    select 1 from public.org_memberships m
    where m.organization_id = v_org_id
      and m.user_id = auth.uid()
      and coalesce(m.is_active, true) = true
      and m.role in ('owner','admin')
  ) then
    raise exception 'No access: owner/admin only';
  end if;

  if exists (
    select 1 from public.field_cycles c
    where c.store_id = p_store_id
      and c.status = 'OPEN'
  ) then
    raise exception 'ACTIVE_FIELD_EXISTS: Close current field before opening a new one';
  end if;

  -- ✅ New field starts fresh, old history stays in transactions
  update public.field_wallets
  set balance = 0,
      updated_at = now()
  where store_id = p_store_id
    and organization_id = v_org_id;

  insert into public.field_cycles (
    organization_id, store_id, title, target_amount, status, opened_by, note
  )
  values (
    v_org_id,
    p_store_id,
    trim(p_title),
    greatest(coalesce(p_target_amount, 0), 0),
    'OPEN',
    auth.uid(),
    nullif(trim(coalesce(p_note, '')), '')
  )
  returning id into v_cycle_id;

  return v_cycle_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.receive_inbound_stock_v1(p_order_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_payload jsonb;
begin
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'item_id', i.id,
        'qty', greatest(coalesce(i.qty_ordered,0) - coalesce(i.qty_received,0), 0)
      )
    ),
    '[]'::jsonb
  )
  into v_payload
  from public.inbound_stock_items i
  where i.inbound_order_id = p_order_id
    and greatest(coalesce(i.qty_ordered,0) - coalesce(i.qty_received,0), 0) > 0;

  if jsonb_array_length(v_payload) = 0 then
    raise exception 'No remaining stock to receive';
  end if;

  return public.receive_inbound_stock_partial_v1(p_order_id, v_payload);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_field_expense_v1(p_store_id uuid, p_membership_id uuid, p_amount numeric, p_note text DEFAULT NULL::text, p_purpose text DEFAULT 'OPERATIONAL'::text, p_category text DEFAULT 'OTHER'::text, p_item_name text DEFAULT NULL::text, p_unit text DEFAULT NULL::text, p_quantity numeric DEFAULT NULL::numeric, p_expected_unit_price numeric DEFAULT NULL::numeric, p_actual_unit_price numeric DEFAULT NULL::numeric, p_variance_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wallet_id uuid;
  v_org_id uuid;
  v_balance_before numeric;
  v_balance_after numeric;
  v_txn_id uuid;
  v_cycle_id uuid;
  v_purpose text;
  v_category text;
  v_item_name text;
  v_unit text;
  v_quantity numeric;
  v_expected numeric;
  v_actual numeric;
  v_variance numeric;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_store_id is null then
    raise exception 'p_store_id is required';
  end if;

  if p_membership_id is null then
    raise exception 'p_membership_id is required';
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Amount must be greater than zero';
  end if;

  select c.id
    into v_cycle_id
  from public.field_cycles c
  where c.store_id = p_store_id
    and c.status = 'OPEN'
  order by c.opened_at desc
  limit 1;

  if v_cycle_id is null then
    raise exception 'NO_ACTIVE_FIELD: Open a field cycle before recording expense';
  end if;

  v_purpose := upper(trim(coalesce(p_purpose, 'OPERATIONAL')));
  v_category := upper(trim(coalesce(p_category, 'OTHER')));

  if v_purpose not in ('TARGET', 'OPERATIONAL') then
    v_purpose := 'OPERATIONAL';
  end if;

  v_item_name := nullif(trim(coalesce(p_item_name, '')), '');
  v_unit := nullif(trim(coalesce(p_unit, '')), '');
  v_quantity := nullif(p_quantity, 0);
  v_expected := nullif(p_expected_unit_price, 0);
  v_actual := nullif(p_actual_unit_price, 0);

  if v_actual is null and v_quantity is not null and v_quantity > 0 then
    v_actual := p_amount / v_quantity;
  end if;

  if v_expected is not null and v_actual is not null then
    v_variance := v_actual - v_expected;
  else
    v_variance := null;
  end if;

  select w.id, w.organization_id, coalesce(w.balance, 0)
    into v_wallet_id, v_org_id, v_balance_before
  from public.field_wallets w
  where w.store_id = p_store_id
    and w.membership_id = p_membership_id
    and coalesce(w.is_active, true) = true
  for update;

  if v_wallet_id is null then
    raise exception 'Wallet not found for this agent';
  end if;

  if v_balance_before < p_amount then
    raise exception 'Insufficient wallet balance';
  end if;

  v_balance_after := v_balance_before - p_amount;

  insert into public.field_wallet_transactions (
    wallet_id,
    organization_id,
    store_id,
    membership_id,
    field_cycle_id,
    type,
    amount,
    balance_before,
    balance_after,
    note,
    purpose,
    category,
    item_name,
    unit,
    quantity,
    expected_unit_price,
    actual_unit_price,
    variance_amount,
    variance_note,
    created_by
  )
  values (
    v_wallet_id,
    v_org_id,
    p_store_id,
    p_membership_id,
    v_cycle_id,
    'EXPENSE',
    p_amount,
    v_balance_before,
    v_balance_after,
    nullif(trim(coalesce(p_note, '')), ''),
    v_purpose,
    v_category,
    v_item_name,
    v_unit,
    v_quantity,
    v_expected,
    v_actual,
    v_variance,
    nullif(trim(coalesce(p_variance_note, '')), ''),
    auth.uid()
  )
  returning id into v_txn_id;

  update public.field_wallets
  set
    balance = v_balance_after,
    updated_at = now()
  where id = v_wallet_id;

  return v_txn_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_expense_v2(p_expense_id uuid, p_amount numeric, p_category text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exp record;
  v_role text;
  v_membership_id uuid;
  v_cat_id uuid;
  v_cat_name text;
  v_payment_method text;
  v_staff_allowed boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select e.*, s.staff_can_manage_expense
  into v_exp
  from public.expenses e
  join public.stores s on s.id = e.store_id
  where e.id = p_expense_id;

  if v_exp.id is null then
    raise exception 'Expense not found';
  end if;

  select m.id, lower(coalesce(m.role, ''))
  into v_membership_id, v_role
  from public.org_memberships m
  where m.user_id = auth.uid()
    and m.organization_id = v_exp.organization_id
    and coalesce(m.is_active, true) = true
  limit 1;

  if v_membership_id is null then
    raise exception 'No access';
  end if;

  if v_role = 'staff' then
    v_staff_allowed := coalesce(v_exp.staff_can_manage_expense, false);

    if not v_staff_allowed then
      raise exception 'Expense permission disabled for staff in this store';
    end if;

    if v_exp.created_by_membership_id <> v_membership_id
       and v_exp.created_by <> auth.uid() then
      raise exception 'Staff can edit own expense only';
    end if;

  elsif v_role = 'admin' then
    if exists (
      select 1
      from public.org_memberships om_owner
      where om_owner.organization_id = v_exp.organization_id
        and lower(coalesce(om_owner.role, '')) = 'owner'
        and (
          om_owner.id = v_exp.created_by_membership_id
          or om_owner.user_id = v_exp.created_by
        )
    ) then
      raise exception 'Admin cannot edit owner expense';
    end if;

  elsif v_role <> 'owner' then
    raise exception 'No access';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  if p_category is not null and length(trim(p_category)) > 0 then
    v_cat_name := trim(p_category);

    select ec.id
    into v_cat_id
    from public.expense_categories ec
    where ec.organization_id = v_exp.organization_id
      and upper(ec.name) = upper(v_cat_name)
    limit 1;

    if v_cat_id is null then
      insert into public.expense_categories (organization_id, name)
      values (v_exp.organization_id, v_cat_name)
      returning id into v_cat_id;
    end if;
  end if;

  v_payment_method := nullif(trim(coalesce(p_payment_method, '')), '');
  if v_payment_method is not null then
    v_payment_method := upper(v_payment_method);
  end if;

  update public.expenses
  set
    amount = p_amount,
    category_id = v_cat_id,
    category_name = v_cat_name,
    note = p_note,
    payment_method = v_payment_method,
    updated_at = now()
  where id = p_expense_id;

  return p_expense_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_purchase_order_status_v1(p_order_id uuid, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  v_status := upper(trim(coalesce(p_status, '')));

  if v_status not in ('PENDING', 'SENT', 'RECEIVED') then
    raise exception 'Invalid status';
  end if;

  select po.organization_id
  into v_org_id
  from public.purchase_orders po
  where po.id = p_order_id;

  if v_org_id is null then
    raise exception 'Order not found';
  end if;

  if not exists (
    select 1
    from public.org_memberships m
    where m.organization_id = v_org_id
      and m.user_id = auth.uid()
      and lower(coalesce(m.role, '')) in ('owner', 'admin')
      and coalesce(m.is_active, true) = true
  ) then
    raise exception 'Only owner/admin can update order status';
  end if;

  update public.purchase_orders
  set
    status = v_status,
    sent_at = case when v_status = 'SENT' and sent_at is null then now() else sent_at end,
    received_at = case when v_status = 'RECEIVED' and received_at is null then now() else received_at end
  where id = p_order_id;

  return true;
end;
$function$
